model.en:
Cap the body as it streams and set explicit timeouts:

import { createServer } from 'node:http';

const MAX = 1_000_000; // 1 MB
const server = createServer(async (req, res) => {
  req.on('error', () => res.destroy()); // handle aborted/error
  let size = 0;
  const chunks = [];
  try {
    for await (const chunk of req) {
      size += chunk.length;
      if (size > MAX) {
        res.writeHead(413).end('payload too large');
        req.destroy();        // stop reading, free the socket
        return;
      }
      chunks.push(chunk);
    }
  } catch { return res.destroy(); }
  const body = Buffer.concat(chunks);
  res.writeHead(200).end('stored ' + body.length);
});

// Slowloris defenses — these are the gap vs a framework
server.requestTimeout = 30_000;  // whole request (default 300000)
server.headersTimeout = 10_000;  // header phase
server.keepAliveTimeout = 5_000; // idle keep-alive
server.listen(3000);

Why it's right: tracking bytes against MAX keeps memory bounded and rejects oversized uploads early with 413 + req.destroy(); setting requestTimeout/headersTimeout reclaims half-open sockets so a slow client can't exhaust the pool; and handling req's error/aborted prevents an aborted upload from crashing the process. These are precisely the safe defaults a framework gives you.

model.ru:
Ограничь тело по мере стриминга и поставь явные таймауты:

import { createServer } from 'node:http';

const MAX = 1_000_000; // 1 МБ
const server = createServer(async (req, res) => {
  req.on('error', () => res.destroy()); // обработай aborted/error
  let size = 0;
  const chunks = [];
  try {
    for await (const chunk of req) {
      size += chunk.length;
      if (size > MAX) {
        res.writeHead(413).end('payload too large');
        req.destroy();        // прекрати чтение, освободи сокет
        return;
      }
      chunks.push(chunk);
    }
  } catch { return res.destroy(); }
  const body = Buffer.concat(chunks);
  res.writeHead(200).end('stored ' + body.length);
});

// Защиты от Slowloris — это и есть брешь vs фреймворк
server.requestTimeout = 30_000;  // весь запрос (дефолт 300000)
server.headersTimeout = 10_000;  // фаза заголовков
server.keepAliveTimeout = 5_000; // простой keep-alive
server.listen(3000);

Почему верно: счёт байт против MAX держит память ограниченной и отвергает слишком большие загрузки рано через 413 + req.destroy(); установка requestTimeout/headersTimeout отбирает полуоткрытые сокеты, так что медленный клиент не исчерпает пул; а обработка error/aborted у req не даёт оборванной загрузке уронить процесс. Это ровно те безопасные дефолты, что даёт фреймворк.
